<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>@Model.Title</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="min-h-screen bg-slate-50 text-slate-900 antialiased">
    <header class="border-b border-slate-200 bg-white">
        <div class="mx-auto max-w-3xl px-6 py-16">
            <h1 class="text-5xl font-bold tracking-tight text-slate-900">@Model.Title</h1>
            @if (!string.IsNullOrWhiteSpace(Model.Intro))
            {
                <p class="mt-4 text-xl leading-relaxed text-slate-600">@Model.Intro</p>
            }
        </div>
    </header>

    <main class="mx-auto max-w-3xl px-6 py-12">
        @await Html.GetBlockGridHtmlAsync(Model, "body")

        <section class="mt-16">
            <h2 class="text-2xl font-bold tracking-tight text-slate-900">Posts</h2>
            <div class="mt-6 space-y-8">
                @foreach (var post in Model.Children<BlogPost>())
                {
                    <article class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm transition hover:shadow-md">
                        <a href="@post.Url()" class="grid gap-0 sm:grid-cols-[auto_1fr]">
                            @if (post.ListingImage is not null)
                            {
                                <img src="@post.ListingImage.GetCropUrl(width: 400, height: 300)"
                                     alt="@post.Title"
                                     class="h-48 w-full object-cover sm:h-full sm:w-48" />
                            }
                            <div class="p-6">
                                <time class="text-sm font-medium text-indigo-600" datetime="@post.PublishDate.ToString("yyyy-MM-dd")">@post.PublishDate.ToString("d MMMM yyyy")</time>
                                <h3 class="mt-2 text-xl font-bold text-slate-900">@post.Title</h3>
                                @if (!string.IsNullOrWhiteSpace(post.Excerpt))
                                {
                                    <p class="mt-2 leading-relaxed text-slate-600">@post.Excerpt</p>
                                }
                            </div>
                        </a>
                    </article>
                }
            </div>
        </section>
    </main>

    <footer class="border-t border-slate-200 bg-white py-8 text-center text-sm text-slate-500">
        Built with Umbraco and MCP.
    </footer>
</body>
</html>

